resident_id, v_total, v_total, _installment_count, 'submitted', _reason, v_actor ) RETURNING plan_id INTO v_plan_id; FOR r IN SELECT bucket, sum(total_amount) AS bucket_amount FROM _plan_charges GROUP BY bucket ORDER BY bucket LOOP INSERT INTO public.arrears_repayment_installment ( woreda_id, plan_id, installment_number, due_date, amount, status ) VALUES ( v_woreda_id, v_plan_id, r.bucket, _installment_due_dates[r.bucket], r.bucket_amount, 'scheduled' ); INSERT INTO public.arrears_installment_charge ( woreda_id, installment_id, rent_charge_id, charge_amount_snapshot, status ) SELECT v_woreda_id, (SELECT installment_id FROM public.arrears_repayment_installment WHERE plan_id = v_plan_id AND installment_number = r.bucket), pc.rent_charge_id, pc.total_amount, 'active' FROM _plan_charges pc WHERE pc.bucket = r.bucket; END LOOP; INSERT INTO public.audit_log (woreda_id, actor_user_id, entity_name, entity_id, action_type, new_value_json) VALUES (v_woreda_id, v_actor, 'arrears_repayment_plan', v_plan_id::text, 'ARREARS_PLAN_CREATED', jsonb_build_object('rent_account_id', _rent_account_id, 'total_arrears', v_total, 'installment_count', _installment_count)); RETURN v_plan_id; END; $function$;

