CREATE OR REPLACE FUNCTION public.guard_arrears_plan_immutable_fields() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN IF NEW.rent_account_id IS DISTINCT FROM OLD.rent_account_id OR NEW.resident_id IS DISTINCT FROM OLD.resident_id OR NEW.plan_number IS DISTINCT FROM OLD.plan_number OR NEW.original_arrears_amount IS DISTINCT FROM OLD.original_arrears_amount OR NEW.assigned_arrears_amount IS DISTINCT FROM OLD.assigned_arrears_amount OR NEW.installment_count IS DISTINCT FROM OLD.installment_count THEN RAISE EXCEPTION 'የክፍያ ዕቅድ የገንዘብ መጠን ወይም ተያያዥ መስኮች ከተፈጠሩ በኋላ ሊቀየሩ አይችሉም / A plan''s amount, installment count and account/resident linkage cannot be changed after creation' USING ERRCODE = 'check_violation'; END IF; IF OLD.requested_by_user_id IS NOT NULL AND NEW.requested_by_user_id IS DISTINCT FROM OLD.requested_by_user_id THEN RAISE EXCEPTION 'guard_arrears_plan_immutable_fields: requested_by_user_id cannot be changed once recorded' USING ERRCODE = 'insufficient_privilege'; END IF; IF OLD.approved_by_user_id IS NOT NULL AND NEW.approved_by_user_id IS NULL THEN RAISE EXCEPTION 'guard_arrears_plan_immutable_fields: approved_by_user_id cannot be cleared once recorded' USING ERRCODE = 'insufficient_privilege'; END IF; IF OLD.approval_decision_at IS NOT NULL AND NEW.approval_decision_at IS NULL THEN RAISE EXCEPTION 'guard_arrears_plan_immutable_fields: approval_decision_at cannot be cleared once recorded' USING ERRCODE = 'insufficient_privilege'; END IF; RETURN NEW; END; $function$;

