CREATE OR REPLACE FUNCTION public.guard_arrears_plan_maker_checker() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN IF NEW.status = 'active' AND OLD.status = 'submitted' THEN IF NEW.approved_by_user_id IS NULL THEN RAISE EXCEPTION 'guard_arrears_plan_maker_checker: an approval must record the approver' USING ERRCODE = 'insufficient_privilege'; END IF; IF NEW.requested_by_user_id IS NULL THEN RAISE EXCEPTION 'guard_arrears_plan_maker_checker: a plan missing its preparer cannot be activated' USING ERRCODE = 'insufficient_privilege'; END IF; IF auth.uid() IS NOT NULL AND NEW.approved_by_user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'guard_arrears_plan_maker_checker: approved_by_user_id must be the caller' USING ERRCODE = 'insufficient_privilege'; END IF; IF NEW.approved_by_user_id = NEW.requested_by_user_id THEN RAISE EXCEPTION 'ጥያቄውን ያዘጋጀው ሠራተኛ ራሱ ማፅደቅ አይችልም / The clerk who prepared this plan cannot also approve it' USING ERRCODE = 'insufficient_privilege'; END IF; IF EXISTS ( SELECT 1 FROM public.arrears_repayment_plan WHERE rent_account_id = NEW.rent_account_id AND status = 'active' AND plan_id <> NEW.plan_id ) THEN RAISE EXCEPTION 'ይህ ሂሳብ ቀድሞውኑ ሌላ ንቁ የክፍያ ዕቅድ አለው USING ERRCODE = 'check_violation'; END IF; END IF; RETURN NEW; END; $function$;

-- ===== guard_console_role_assignment (latest @ supabase/migrations/00000000000012_enforce_console_rbac.sql:94) =====
CREATE OR REPLACE FUNCTION public.guard_console_role_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path TO 'public' AS $function$ DECLARE becomes_unrestricted boolean; BEGIN IF auth.uid() IS NULL THEN RETURN NEW; END IF; becomes_unrestricted := NEW.role = 'super_admin' AND NEW.console_role_id IS NULL AND (TG_OP = 'INSERT' OR OLD.role IS DISTINCT FROM 'super_admin' OR OLD.console_role_id IS NOT NULL); IF TG_OP = 'UPDATE' AND NEW.console_role_id IS NOT DISTINCT FROM OLD.console_role_id AND NOT becomes_unrestricted THEN RETURN NEW; END IF; IF NEW.console_role_id IS NULL AND NEW.role <> 'super_admin' THEN RETURN NEW; END IF; IF NEW.user_id = auth.uid() THEN RAISE EXCEPTION 'Cannot change your own console_role_id'; END IF; IF NOT public.user_has_console_perm('console.console_users.manage') THEN RAISE EXCEPTION 'Only an admin with console.console_users.manage may change console_role_id'; END IF; RETURN NEW; END; $function$;

