-- ===== luhn_check_digit (latest @ supabase/migrations/00000000000002_credential.sql:22) =====
CREATE OR REPLACE FUNCTION public.luhn_check_digit(_digits TEXT) RETURNS INT LANGUAGE plpgsql IMMUTABLE AS $function$ DECLARE v_sum INT := 0; v_digit INT; i INT; BEGIN IF _digits IS NULL OR _digits !~ '^[0-9]+$' THEN RAISE EXCEPTION 'luhn_check_digit: expected digits only, got %', _digits; END IF; FOR i IN 1..length(_digits) LOOP v_digit := substring(_digits FROM (length(_digits) - i + 1) FOR 1)::INT; IF i % 2 = 1 THEN v_digit := v_digit * 2; IF v_digit > 9 THEN v_digit := v_digit - 9; END IF; END IF; v_sum := v_sum + v_digit; END LOOP; RETURN (10 - (v_sum % 10)) % 10; END; $function$;

