CREATE OR REPLACE FUNCTION public.validate_tenant_role_name() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN IF lower(trim(NEW.name)) = ANY (ARRAY[ 'super_admin', 'tenant_admin', 'civil_registrar', 'registry_clerk', 'finance_clerk', 'supervisor', 'auditor', 'viewer', 'print_officer', 'custom' ]) THEN RAISE EXCEPTION 'tenant_role name "%" is reserved for a built-in role', NEW.name; END IF; RETURN NEW; END; $function$;

-- ===== verify_credential_token (latest @ supabase/migrations/00000000000034_task3_harden_credential_verification.sql:145) =====
CREATE FUNCTION public.verify_credential_token(_token TEXT) RETURNS TABLE( credential_number TEXT, status TEXT, issue_date DATE, expiry_date DATE, resident_full_name TEXT, woreda_name_am TEXT, woreda_name_en TEXT, kebele_name_am TEXT, kebele_name_en TEXT, photo_path TEXT, date_of_birth DATE ) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_is_staff boolean := public.is_active_app_user(); v_headers jsonb; v_ip text; v_hits integer; v_row RECORD; v_raw_status text; v_public_status text; BEGIN IF _token IS NULL OR btrim(_token) = '' THEN RAISE EXCEPTION 'verify_credential_token: token is required' USING ERRCODE = 'invalid_parameter_value'; END IF; BEGIN v_headers := nullif(current_setting('request.headers', true), '')::jsonb; EXCEPTION WHEN OTHERS THEN v_headers := NULL; END; v_ip := COALESCE( v_headers ->> 'cf-connecting-ip', v_headers ->> 'x-real-ip', nullif(btrim(split_part(v_headers ->> 'x-forwarded-for', ',', 1)), '') ); IF NOT v_is_staff THEN v_hits := NULL; BEGIN v_hits := public.rate_limit_hit('verify_credential_token:' || COALESCE(v_ip, 'unknown'), 60); EXCEPTION WHEN OTHERS THEN v_hits := NULL; END; IF v_hits IS NOT NULL AND v_hits > 30 THEN RAISE EXCEPTION 'Too many requests' USING ERRCODE = 'insufficient_resources'; END IF; END IF; SELECT rc.credential_id, rc.woreda_id, rc.credential_number, rc.status::text, rc.issue_date, rc.expiry_date, COALESCE(r.full_name_am, r.full_name) AS resident_full_name, w.woreda_name_am, w.woreda_name_en, k.kebele_name_am, k.kebele_name_en, r.photo_url, r.date_of_birth INTO v_row FROM public.residence_credential rc LEFT JOIN public.resident r ON r.resident_id = rc.resident_id LEFT JOIN public.woreda w ON w.woreda_id = rc.woreda_id LEFT JOIN public.kebele k ON k.kebele_id = rc.issuing_kebele_id WHERE rc.qr_payload = _token OR ( v_is_staff AND (public.is_super_admin() OR rc.woreda_id = public.get_user_woreda_id()) AND replace(rc.credential_number, '-', '') = _token ) LIMIT 1; IF NOT FOUND THEN INSERT INTO public.credential_verification_log (attempted_value_kind, attempted_value, result, is_staff_caller, source_ip) VALUES ( CASE WHEN _token ~ '^[0-9]{13}$' THEN 'credential_number' ELSE 'token' END, left(_token, 512), 'not_found', v_is_staff, v_ip ); RETURN; END IF; v_raw_status := v_row.status; v_public_status := CASE WHEN NOT v_is_staff AND v_raw_status IN ('expired', 'suspended', 'revoked', 'replaced') THEN 'invalid' ELSE v_raw_status END; INSERT INTO public.credential_verification_log (woreda_id, matched_credential_id, attempted_value_kind, attempted_value, result, is_staff_caller, source_ip) VALUES ( v_row.woreda_id, v_row.credential_id, CASE WHEN v_is_staff AND replace(v_row.credential_number, '-', '') = _token THEN 'credential_number' ELSE 'token' END, left(_token, 512), CASE WHEN v_raw_status IN ('expired', 'suspended', 'revoked', 'replaced') THEN 'invalid' ELSE 'valid' END, v_is_staff, v_ip ); RETURN QUERY SELECT v_row.credential_number, v_public_status, v_row.issue_date, v_row.expiry_date, v_row.resident_full_name, v_row.woreda_name_am, v_row.woreda_name_en, v_row.kebele_name_am, v_row.kebele_name_en, CASE WHEN v_is_staff THEN v_row.photo_url END, CASE WHEN v_is_staff THEN v_row.date_of_birth END; END; $function$;

-- ===== verify_receipt (latest @ supabase/migrations/00000000000013_receipt_verification.sql:134) =====
CREATE OR REPLACE FUNCTION public.verify_receipt(_token text) RETURNS TABLE( receipt_number text, receipt_date date, total_amount numeric, payment_type text, channel text, printed_at timestamp with time zone, paid_by_full_name text, paid_by_full_name_am text, woreda_name_am text, woreda_name_en text, kebele_name_am text, kebele_name_en text ) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT r.receipt_number, r.receipt_date, r.total_amount, p.payment_type, r.cash_bank_channel, r.printed_at, res.full_name, res.full_name_am, w.woreda_name_am, w.woreda_name_en, k.kebele_name_am, k.kebele_name_en FROM public.receipt r JOIN public.payment p ON p.payment_id = r.payment_id AND p.woreda_id = r.woreda_id LEFT JOIN public.rental_occupancy_request ror ON ror.rental_request_id = p.rental_request_id AND ror.woreda_id = r.woreda_id LEFT JOIN public.kebele_rental_house krh ON krh.rental_house_id = ror.rental_house_id AND krh.woreda_id = r.woreda_id LEFT JOIN public.resident res ON res.resident_id = COALESCE(p.resident_id, ror.resident_id) AND res.woreda_id = r.woreda_id LEFT JOIN public.household h ON h.household_id = p.household_id AND h.woreda_id = r.woreda_id LEFT JOIN public.woreda w ON w.woreda_id = r.woreda_id LEFT JOIN public.kebele k ON k.kebele_id = COALESCE(h.kebele_id, krh.kebele_id) AND k.woreda_id = r.woreda_id WHERE r.verification_token = _token AND p.status = 'confirmed' LIMIT 1 $function$;

-- ===== verify_service_letter (latest @ supabase/migrations/00000000000064_task14b_verify_letter_completed_status.sql:22) =====
CREATE OR REPLACE FUNCTION public.verify_service_letter(_token text) RETURNS TABLE(request_number text, issued_at timestamp with time zone, subject text, resident_full_name text, letter_summary text, service_type_am text, service_type_en text, woreda_name_am text, woreda_name_en text, kebele_name_am text, kebele_name_en text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT sr.request_number, sr.issued_at, sr.subject, COALESCE(r.full_name_am, r.full_name, sr.applicant_name), COALESCE(sr.letter_summary, sr.purpose), st.name_am, st.name_en, w.woreda_name_am, w.woreda_name_en, k.kebele_name_am, k.kebele_name_en FROM public.service_request sr LEFT JOIN public.resident r ON r.resident_id = sr.resident_id LEFT JOIN public.service_type st ON st.service_type_id = sr.service_type_id LEFT JOIN public.woreda w ON w.woreda_id = sr.woreda_id LEFT JOIN public.kebele k ON k.kebele_id = sr.kebele_id WHERE sr.verification_token = _token AND sr.issued_at IS NOT NULL AND sr.status IN ('issued', 'resolved', 'closed', 'completed') LIMIT 1; $function$;

